function showReport(report,combined=false){reportMode=combined?'library':'current';$('recordView').hidden=report;$('recordPeriod').hidden=report;$('reportView').hidden=!report;$('libraryPanel').hidden=!combined;for(const [id,on] of [['recordTab',!report],['reportTab',report&&!combined],['allReportTab',report&&combined]]){$(id).classList.toggle('selected',on);$(id).setAttribute('aria-pressed',on);}if(report){populateFilters();renderReport();}}
function populateFilters(){if(typeof buildFilters==='function')buildFilters();}
function populatePlayerFilter(){buildFilters();}
function heatField(points,sigma=7,w=200,h=110){const field=new Float32Array(w*h),dx=200/w,dy=110/h,radius=sigma*4;for(const p of points){const loX=Math.max(0,Math.ceil((p.x-radius+10)/dx-.5)),hiX=Math.min(w-1,Math.floor((p.x+radius+10)/dx-.5)),loY=Math.max(0,Math.ceil((p.y-radius+10)/dy-.5)),hiY=Math.min(h-1,Math.floor((p.y+radius+10)/dy-.5)),weights=[];for(let i=loX;i<=hiX;i++)weights.push(Math.exp(-((-10+(i+.5)*dx-p.x)**2)/(2*sigma*sigma)));for(let j=loY;j<=hiY;j++){const yy=Math.exp(-((-10+(j+.5)*dy-p.y)**2)/(2*sigma*sigma));for(let i=loX;i<=hiX;i++)field[j*w+i]+=weights[i-loX]*yy;}}let max=0;for(const n of field)max=Math.max(max,n);return {field,max,w,h};}
