  if(kind==='input'){c.fillStyle='#dca64f';c.fillRect(left,top,w,h);for(let y=0;y<90;y+=2.5){c.strokeStyle=y%5===0?'#b7823530':'#f3d59c25';c.lineWidth=.7;c.beginPath();c.moveTo(X(0),Y(y));c.lineTo(X(180),Y(y));c.stroke();}}
  else{c.fillStyle='#3287b1';c.fillRect(left,top,w,h);if(heat&&heatMax){const layer=document.createElement('canvas');layer.width=heat.w;layer.height=heat.h;const lc=layer.getContext('2d'),im=lc.createImageData(heat.w,heat.h);for(let i=0;i<heat.field.length;i++)im.data.set([...heatColor(heat.field[i]/heatMax),255],i*4);lc.putImageData(im,0,0);c.drawImage(layer,X(-10),Y(-10),800,440);}}
  c.font='12px Malgun Gothic, sans-serif';c.textAlign='center';for(const goalSide of ['left','right'])for(const atTop of [true,false]){const out=(goalSide==='left')===atTop?'left':'right',xx=goalSide==='left'?70:430,yy=atTop?34:421;c.fillStyle=kind==='input'?'#dedbcf':'#edf2f233';c.fillRect(xx,atTop?20:420,360,40);c.fillStyle='#68756e';c.fillText((out==='right'?'0':'8')+'구역 아웃',xx+180,yy+17);}
  const line=(x1,y1,x2,y2)=>{c.beginPath();c.moveTo(X(x1),Y(y1));c.lineTo(X(x2),Y(y2));c.stroke();};
