  for(const end of [0,180]){const d=end===0?1:-1;line(end+d*15,0,end+d*15,15);line(end+d*15,75,end+d*15,90);line(end,45,end+d*5,45);line(end+d*30,45,end+d*25,45);line(end,15,end+d*1.5,15);line(end,75,end+d*1.5,75);}
