  c.font='12px Malgun Gothic, sans-serif';c.fillText(kind==='input'?'벤치 · 왼쪽 아래 1 / 오른쪽 위 1':'팀 기준 · 각 골대 오른쪽이 1',430,465);c.font='10px Malgun Gothic, sans-serif';c.fillText('18 m / 180',430,489);
