$('exportButton').onclick=download;$('importButton').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('10MB 이하 JSON 파일을 선택하세요.');const next=migrate(JSON.parse(await f.text()));if(await confirmReplace()){match=next;afterReplace();$('menuDialog').close();if(!match.registered)openMenu();notice('v3로 기록을 불러왔습니다. 기존 좌표와 이벤트는 유지합니다.');}}catch(e){notice(e.message||'파일을 읽지 못했습니다.');}finally{e.target.value='';}};
