// v3 analysis stays separate from the live match and the v2 storage namespace.
let reportMode='current',library=[],selectedGames=new Set(),filterState={current:{},library:{}},timelineGameKey=null,timelineExpanded=true;
const FACTORS=[['half','경기 구간'],['team','팀'],['player','선수'],['start','출발 구역'],['release','릴리스 구역'],['course','도착 구역'],['technique','기술유형'],['event','이벤트']];
function exportName(m,now=new Date()){const clean=m.name.replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').replace(/[. ]+$/g,'').slice(0,70)||'경기';const time=now.toLocaleTimeString('sv-SE',{hour12:false}).replace(/:/g,'');return `${m.date}_${clean}_골볼-v3_${time}.json`;}
function gameKey(m){return m.id||'legacy:'+JSON.stringify([m.date,m.name,m.teams.A.name,m.teams.B.name,m.records[0]?.id||'empty']);}
function analysisGames(){return reportMode==='current'?[match]:library.filter(m=>selectedGames.has(gameKey(m)));}
function gameLabel(m){return `${m.date} · ${m.name}`;}
function normalizedName(value){return String(value||'').normalize('NFC').trim().replace(/\s+/g,' ').toLocaleLowerCase();}
function teamKey(m,t){return reportMode==='library'?JSON.stringify(['team',normalizedName(m.teams[t].name)]):JSON.stringify([gameKey(m),t]);}
function rosterPlayer(m,t,n){const current=m.teams[t].players.find(p=>p.number===n);if(current)return current;for(const r of [...m.records].reverse())if(r.team===t&&r.before){const p=[...r.after,...r.before].find(p=>p.number===n);if(p)return p;}return {number:n,name:''};}
function playerKey(m,t,n){const p=rosterPlayer(m,t,n);return reportMode==='library'?JSON.stringify([teamKey(m,t),String(Number(n)),normalizedName(p.name)]):JSON.stringify([gameKey(m),t,n]);}
function filters(){return filterState[reportMode];}
function includesFactor(k,v){return !filters()[k]?.length||filters()[k].includes(v);}
function zoneValue(p,side){const n=pointZone(p,side);return n==null?'unknown':String(n);}
function eventMatches(r,values){return !values?.length||values.some(v=>v==='foul'?r.result.startsWith('foul'):Object.hasOwn(TYPE,v)?r.throwType===v:r.result===v);}
function analysisRows(ignorePlayer=false){const rows=[];for(const m of analysisGames())for(const r of m.records){if(r.kind!=='throw'||!includesFactor('half',r.half)||!includesFactor('team',teamKey(m,r.team))||(!ignorePlayer&&!includesFactor('player',playerKey(m,r.team,r.player)))||!includesFactor('start',zoneValue(r.start,attackSide(r)))||!includesFactor('release',zoneValue(r.release,attackSide(r)))||!includesFactor('course',zoneValue(r.target,receivingSide(r)))||!includesFactor('technique',r.technique||'unselected')||!eventMatches(r,filters().event))continue;rows.push({...normalizeThrow(r),sourceMatch:m,sourceKey:gameKey(m)});}return rows;}
function factorOptions(key){const games=analysisGames(),zones=[0,1,2,3,4,5,6,8].map(n=>[String(n),`${n}구역${n===0||n===8?' 아웃':''}`]);if(key==='half')return [['first','전반'],['second','후반']];if(['start','release','course'].includes(key))return [...zones,['unknown','위치 미확인']];if(key==='technique')return [...TECHNIQUES.map(t=>[t,t]),['unselected','미선택']];if(key==='event')return [['normal','일반투구'],['penalty','페널티투구'],['goal','골 G'],['foulL','파울 L'],['foulH','파울 H'],['foul','파울 전체']];if(key==='team'){const teams=new Map();for(const m of games)for(const t of ['A','B'])teams.set(teamKey(m,t),m.teams[t].name);return [...teams];}if(key==='player'){const players=new Map();for(const m of games)for(const t of ['A','B']){const roster=new Map(m.teams[t].players.map(p=>[p.number,p]));for(const r of m.records){if(r.kind==='throw'&&r.team===t&&!roster.has(r.player))roster.set(r.player,rosterPlayer(m,t,r.player));if(r.team===t&&r.before)for(const p of [...r.before,...r.after])if(!roster.has(p.number))roster.set(p.number,p);}for(const p of roster.values())players.set(playerKey(m,t,p.number),`${m.teams[t].name} ${p.number}번${p.name?' '+p.name:''}`);}return [...players];}return [];}
function buildFilters(){const parent=$('reportFilters');parent.replaceChildren();$('libraryTeamChoice').replaceChildren();for(const [key,label] of FACTORS){const options=factorOptions(key),valid=new Set(options.map(o=>o[0]));filters()[key]=(filters()[key]||[]).filter(v=>valid.has(v));const detail=document.createElement('details');detail.className='factor-select';const summary=document.createElement('summary');const update=()=>{summary.textContent=label+' · '+(filters()[key]?.length?filters()[key].length+'개 선택':'전체');};update();const list=document.createElement('div');list.className='factor-options';const all=document.createElement('button');all.textContent='전체';all.type='button';all.onclick=()=>{filters()[key]=[];for(const input of list.querySelectorAll('input'))input.checked=false;update();renderReport();};list.append(all);for(const [value,text] of options){const row=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=filters()[key].includes(value);input.onchange=()=>{const chosen=new Set(filters()[key]);input.checked?chosen.add(value):chosen.delete(value);filters()[key]=[...chosen];update();renderReport();};row.append(input,document.createTextNode(text));list.append(row);}detail.append(summary,list);detail.addEventListener('toggle',()=>{if(detail.open)for(const other of document.querySelectorAll('.factor-select'))if(other!==detail)other.open=false;});(reportMode==='library'&&key==='team'?$('libraryTeamChoice'):parent).append(detail);}const clear=document.createElement('button');clear.className='text-button';clear.textContent='요인 초기화';clear.onclick=()=>{filterState[reportMode]={};buildFilters();renderReport();};parent.append(clear);}
function groupPlots(rows,totals){if(reportMode==='library'){const groups=rows.length?[{label:'선택 경기 · 분석 투구 통합 합계',records:rows,total:true,aggregate:true}]:[],players=new Map(),teams=new Map();for(const r of rows){const tk=teamKey(r.sourceMatch,r.team);if(!teams.has(tk))teams.set(tk,{label:`${r.sourceMatch.teams[r.team].name} · 전체 경기 통합`,teamName:r.sourceMatch.teams[r.team].name,total:true,records:[]});teams.get(tk).records.push(r);const key=playerKey(r.sourceMatch,r.team,r.player),p=rosterPlayer(r.sourceMatch,r.team,r.player);if(!players.has(key))players.set(key,{label:`${r.sourceMatch.teams[r.team].name} ${p.number}번${p.name?' '+p.name:''} · 전체 경기`,records:[],teamName:r.sourceMatch.teams[r.team].name});players.get(key).records.push(r);}return [...groups,...teams.values(),...[...players.values()].sort((a,b)=>a.label.localeCompare(b.label,'ko',{numeric:true}))];}const groups=[];for(const m of analysisGames()){for(const t of ['A','B']){if(!includesFactor('team',teamKey(m,t)))continue;groups.push({label:`${m.teams[t].name} · 팀 전체 합`,records:totals.filter(r=>r.sourceKey===gameKey(m)&&r.team===t),total:true,teamName:m.teams[t].name});}const players=new Map();for(const r of rows.filter(r=>r.sourceKey===gameKey(m))){const key=r.team+':'+r.player,p=rosterPlayer(m,r.team,r.player);if(!players.has(key))players.set(key,{label:`${m.teams[r.team].name} ${p.number}번${p.name?' '+p.name:''}`,records:[],teamName:m.teams[r.team].name});players.get(key).records.push(r);}groups.push(...players.values());}return groups;}
function usageSummary(rows){const teams=new Map();for(const r of rows){const tk=teamKey(r.sourceMatch,r.team);if(!teams.has(tk))teams.set(tk,{name:r.sourceMatch.teams[r.team].name,total:0,players:new Map()});const t=teams.get(tk);t.total++;const pk=playerKey(r.sourceMatch,r.team,r.player),p=rosterPlayer(r.sourceMatch,r.team,r.player);if(!t.players.has(pk))t.players.set(pk,{label:`${p.number}번${p.name?' '+p.name:''}`,count:0,courses:new Map(),patterns:new Map()});const entry=t.players.get(pk);entry.count++;const zone=zoneValue(r.target,receivingSide(r));entry.courses.set(zone,(entry.courses.get(zone)||0)+1);const pattern=[zoneValue(r.start,attackSide(r)),zoneValue(r.release,attackSide(r)),zone].map(z=>z==='unknown'?'미확인':z).join('-');entry.patterns.set(pattern,(entry.patterns.get(pattern)||0)+1);}return [...teams.values()].map(t=>({...t,players:[...t.players.values()].sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,'ko',{numeric:true})).map(p=>({...p,percent:p.count/t.total*100,patterns:[...p.patterns].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'ko',{numeric:true})).map(([pattern,count])=>({pattern,count,percent:count/p.count*100})),courses:[...p.courses].sort((a,b)=>b[1]-a[1]||Number(a[0])-Number(b[0])).map(([zone,count])=>({zone,count,percent:count/p.count*100}))}))}));}
function renderUsageSummary(rows){const parent=$('usageSummary');parent.replaceChildren();parent.hidden=!rows.length;for(const t of usageSummary(rows)){const section=document.createElement('section'),lead=document.createElement('p');lead.innerHTML=`<strong>${html(t.name)}</strong> · 주요 투구 ${t.players.slice(0,3).map(p=>`${html(p.label)} ${p.count}회 (${p.percent.toFixed(1)}%)`).join(' · ')}`;section.append(lead);const detail=document.createElement('details'),summary=document.createElement('summary');summary.textContent='선수별 투구 · 주요 도착 코스 · 코스 패턴';detail.append(summary);const table=document.createElement('table');table.innerHTML='<thead><tr><th>선수</th><th>투구 빈도</th><th>주요 도착 코스 (상위 3개)</th><th>주요 코스 패턴 (상위 3개)</th></tr></thead>';const body=document.createElement('tbody');for(const p of t.players){const tr=document.createElement('tr');tr.innerHTML=`<td>${html(p.label)}</td><td>${p.count}회 (${p.percent.toFixed(1)}%)</td><td>${p.courses.slice(0,3).map(c=>`${c.zone==='unknown'?'미확인':c.zone+'구역'} ${c.count}회 (${c.percent.toFixed(1)}%)`).join(' · ')}</td><td>${p.patterns.slice(0,3).map(c=>`${html(c.pattern)} ${c.count}회 (${c.percent.toFixed(1)}%)`).join('<br>')}</td>`;body.append(tr);}table.append(body);const tableWrap=document.createElement('div');tableWrap.className='usage-table';tableWrap.append(table);detail.append(tableWrap);section.append(detail);parent.append(section);}const note=document.createElement('p');note.className='analysis-note';note.textContent='선택 조건 기준 · 투구 비율은 해당 팀 분석 투구 대비, 코스·패턴 비율은 해당 선수 분석 투구 대비 · 패턴은 출발–릴리스–도착';parent.append(note);}
function renderReport(){const rows=analysisRows(),plots=groupPlots(rows,analysisRows(true)),maps=plots.map(g=>heatField(g.records.flatMap(r=>[r.start,r.release,r.target].filter(p=>p&&!p.out)))),max=Math.max(0,...maps.map(m=>m.max));$('aggregateFigure').hidden=reportMode!=='library';$('aggregateFigure').replaceChildren();renderUsageSummary(rows);$('teamFigures').replaceChildren();$('reportFigures').replaceChildren();$('reportEmpty').hidden=!!rows.length;renderOverview();renderSubstitutions();plots.forEach((g,i)=>{const f=document.createElement('figure');f.className='report-figure';const title=document.createElement('figcaption');title.textContent=`${g.label} (N = ${g.records.length})`;const canvas=document.createElement('canvas');canvas.width=860;canvas.height=500;canvas.setAttribute('role','img');canvas.setAttribute('aria-label',title.textContent+', 출발 릴리스 도착 궤적과 아웃을 포함한 위치 빈도');const goals=g.records.filter(r=>r.result==='goal').length,fouls=g.records.filter(r=>r.result.startsWith('foul')).length,summary=document.createElement('p');summary.className='figure-summary';summary.textContent=`골 ${goals} · 파울 ${fouls} (L ${g.records.filter(r=>r.result==='foulL').length} / H ${g.records.filter(r=>r.result==='foulH').length}) · 득점률 ${g.records.length?(goals/g.records.length*100).toFixed(1)+'%':'—'}`;const z=zoneStats(g.records),frequency=document.createElement('div');frequency.className='zone-frequency';frequency.innerHTML=`<span>도착 0 · 1 · 2 · 3 · 4 · 5 · 6 · 8구역</span><div>횟수: ${[z.outs.right,...z.counts,z.outs.left].join(', ')}</div><div>비율(%): ${[z.outPercent.right,...z.percent,z.outPercent.left].map(n=>Number(n.toFixed(1))).join(', ')}</div>`;f.append(title,canvas,summary,frequency);const legacy=g.records.filter(r=>[r.start,r.release,r.target].some(p=>!p||p.out)).length;if(legacy){const note=document.createElement('p');note.className='figure-summary';note.textContent=`이전 위치 미확인 기록 ${legacy}건 · 방향 아웃은 회색 점으로 표시`;f.append(note);}$(g.aggregate?'aggregateFigure':g.total?'teamFigures':'reportFigures').append(f);drawCourt(canvas,{kind:'report',records:g.records,heat:maps[i],heatMax:max,teamName:g.teamName||g.label});});}
function score(m){const goals={A:0,B:0};for(const r of m.records)if(r.kind==='throw'&&r.result==='goal'&&includesFactor('half',r.half))goals[r.team]++;return goals;}
function overviewGame(games){if(!games.length){timelineGameKey=null;return null;}const chosen=games.find(m=>gameKey(m)===timelineGameKey)||games[0];timelineGameKey=gameKey(chosen);return chosen;}
function initialRoster(m,t){return structuredClone(m.records.find(r=>r.team===t&&r.before)?.before||m.teams[t].players);}
function librarySummaryData(){const games=analysisGames().filter(m=>['A','B'].some(t=>includesFactor('team',teamKey(m,t)))),rows=analysisRows(),players=new Map();for(const m of games){const gd=ganttData(m);for(const seg of gd.segments){if(!seg.player||!includesFactor('team',teamKey(m,seg.team)))continue;const p=rosterPlayer(m,seg.team,seg.player.number),key=playerKey(m,seg.team,p.number);if(!players.has(key))players.set(key,{label:`${m.teams[seg.team].name} ${p.number}번${p.name?' '+p.name:''}`,throws:0,goals:0,fouls:0});}}for(const r of rows){const key=playerKey(r.sourceMatch,r.team,r.player),p=rosterPlayer(r.sourceMatch,r.team,r.player);if(!players.has(key))players.set(key,{label:`${r.sourceMatch.teams[r.team].name} ${p.number}번${p.name?' '+p.name:''}`,throws:0,goals:0,fouls:0});const entry=players.get(key);entry.throws++;if(r.result==='goal')entry.goals++;if(r.result.startsWith('foul'))entry.fouls++;}const goals=rows.filter(r=>r.result==='goal').length,fouls=rows.filter(r=>r.result.startsWith('foul')).length;return {games:games.length,throws:rows.length,goals,fouls,players:[...players.values()].map(p=>({...p,rate:p.throws?(p.goals/p.throws*100).toFixed(1):'—'})).sort((a,b)=>a.label.localeCompare(b.label,'ko',{numeric:true})),rate:rows.length?(goals/rows.length*100).toFixed(1):'—'};}
function renderLibrarySummary(){const d=librarySummaryData(),parent=$('librarySummary');parent.replaceChildren();const metrics=document.createElement('div');metrics.className='analysis-metrics';for(const [label,value] of [['분석 경기',d.games+'경기'],['분석 투구',d.throws+'회'],['골 · 파울',d.goals+' · '+d.fouls],['득점률',d.rate==='—'?'—':d.rate+'%']]){const box=document.createElement('div');box.innerHTML=`<span>${label}</span><strong>${html(value)}</strong>`;metrics.append(box);}parent.append(metrics);const details=document.createElement('details');details.className='analysis-roster';const summary=document.createElement('summary');summary.textContent=`출전 선수 ${d.players.length}명 · 선수별 기록 요약`;details.append(summary);const list=document.createElement('div');list.className='analysis-roster-list';for(const p of d.players){const row=document.createElement('p');row.textContent=`${p.label} · 투구 ${p.throws}회 · 골 ${p.goals} · 득점률 ${p.rate==='—'?'—':p.rate+'%'} · 파울 ${p.fouls}`;list.append(row);}details.append(list);parent.append(details);const note=document.createElement('p');note.className='analysis-note';note.textContent='경기 수·출전 명단은 경기와 팀 기준, 투구·골·파울은 아래 요인 필터 기준입니다. 선수는 같은 팀·번호·이름 기준으로 통합합니다.';parent.append(note);}
function renderOverview(){const parent=$('matchOverview');parent.replaceChildren();parent.hidden=reportMode==='library';$('librarySummary').hidden=reportMode!=='library';if(reportMode==='library'){renderLibrarySummary();return;}const m=match,card=document.createElement('section');card.className='score-card';const head=document.createElement('div');head.className='score-heading';const name=document.createElement('span');name.textContent=gameLabel(m);head.append(name);const sc=score(m),scoreLabel=document.createElement('strong');scoreLabel.innerHTML=`${html(m.teams.A.name)} <b>${sc.A} : ${sc.B}</b> ${html(m.teams.B.name)}`;const note=document.createElement('small');note.textContent='기록된 골 기준 · 전반 왼쪽 팀은 위, 전반 오른쪽 팀은 아래 · 선과 이벤트는 경기 구간 조건 적용 · 선수 위치는 기록 당시 기준';head.append(scoreLabel,note);const disclosure=document.createElement('details');disclosure.className='timeline-disclosure';disclosure.open=timelineExpanded;const summary=document.createElement('summary');summary.textContent='투구 시퀀스 · 이벤트 타임라인';disclosure.append(summary,timeline(m));disclosure.addEventListener('toggle',()=>{if(disclosure.isConnected)timelineExpanded=disclosure.open;});card.append(head,disclosure);parent.append(card);}
function timelineData(m){let index=0;const goals={A:0,B:0},points={A:[{x:0,y:0}],B:[{x:0,y:0}]},events=[];for(const r of m.records){if(r.kind==='throw')index++;if(!includesFactor('half',r.half))continue;let code=null,time=r.resultTime||r.eventTime||null;if(r.kind==='throw'){if(r.result==='goal'){goals[r.team]++;code='G';}else if(r.result.startsWith('foul'))code=r.result==='foulL'?'L':r.result==='foulH'?'H':'파울';else if(r.throwType==='penalty')code='P';}else code=r.kind==='positionChange'?'포지션':'교체';for(const t of ['A','B'])points[t].push({x:index,y:goals[t]});if(code)events.push({x:index,y:goals[r.team],team:r.team,code,time,half:r.half,player:r.player,kind:r.kind});}return {points,events,total:index,goals};}
function timelineLabel(e){return [`${e.x}회`,`${e.player?e.player+'번 ':''}${e.code}`,e.time||'—'];}
function ganttData(m){const total=m.records.filter(r=>r.kind==='throw').length,segments=[],events=[],rosters={A:initialRoster(m,'A'),B:initialRoster(m,'B')},opened={A:{},B:{}};for(const t of ['A','B'])for(const pos of ['L','C','R']){const p=rosters[t].find(p=>p.active&&p.position===pos);if(p)opened[t][pos]={team:t,position:pos,start:0,player:{...p}};}let n=0,boundary=null;for(const r of m.records){if(r.half==='second'&&boundary===null)boundary=n;if(r.kind==='throw'){n++;const p=rosters[r.team].find(p=>p.number===r.player&&p.active),position=p?.position||'?';let code=r.result==='goal'?'G':r.result==='foulL'?'L':r.result==='foulH'?'H':r.result==='foul'?'파울':r.throwType==='penalty'?'P':null;if(code)events.push({x:n,team:r.team,position,player:r.player,code,time:r.resultTime||null,half:r.half,kind:'throw'});}else if(r.before){for(const pos of ['L','C','R']){const old=rosters[r.team].find(p=>p.active&&p.position===pos),next=r.after.find(p=>p.active&&p.position===pos);if(old?.number!==next?.number){if(opened[r.team][pos])segments.push({...opened[r.team][pos],end:n});delete opened[r.team][pos];if(next)opened[r.team][pos]={team:r.team,position:pos,start:n,player:{...next}};events.push({x:n,team:r.team,position:pos,player:next?.number,code:r.kind==='positionChange'||(next&&rosters[r.team].some(p=>p.active&&p.number===next.number))?'위치':'교체',before:old?.number||null,time:r.eventTime||null,half:r.half,kind:r.kind});}}rosters[r.team]=structuredClone(r.after);}}for(const t of ['A','B'])for(const seg of Object.values(opened[t]))segments.push({...seg,end:total});return {total,segments,events,boundary};}
function sequenceData(m){const rosters={A:initialRoster(m,'A'),B:initialRoster(m,'B')},points={A:[],B:[]};let n=0;for(const r of m.records){if(r.kind==='throw'){n++;if(!includesFactor('half',r.half))continue;const p=rosters[r.team].find(p=>p.number===r.player&&p.active);points[r.team].push({x:n,position:p?.position||'?',player:r.player,half:r.half});}else if(r.before)rosters[r.team]=structuredClone(r.after);}return points;}
function eventIcon(code){return ({G:'★',L:'△',H:'▽',P:'◇','파울':'△','교체':'↔','위치':'↕'})[code]||'•';}
function timelineSVG(m){
 const data=ganttData(m),points=sequenceData(m),events=data.events.filter(e=>includesFactor('half',e.half)),colors={A:'#245f91',B:'#b05b30'},roles={};
 for(const t of ['A','B'])roles[t]=['L','C','R',...(points[t].some(p=>p.position==='?')||events.some(e=>e.team===t&&e.position==='?')?['?']:[])];
 const centerTop=0,centerBottom=112,centerY=56,H=centerBottom+(roles.A.length+roles.B.length)*24+60,left=145;
 const grouped=new Map();for(const e of events){const key=[e.team,e.x,e.kind,e.time].join(':');if(!grouped.has(key))grouped.set(key,{...e,changes:[]});grouped.get(key).changes.push(e);}
 const markers=[...grouped.values()],lastEvent={A:-1000,B:-1000},xs=[left];for(let n=1;n<=data.total;n++){let x=xs[n-1]+14;for(const e of markers.filter(e=>e.x===n))x=Math.max(x,lastEvent[e.team]+58);xs[n]=x;for(const e of markers.filter(e=>e.x===n))lastEvent[e.team]=x;}
 const W=Math.max(860,xs[data.total]+120),right=W-24,X=n=>xs[n]??left,Y=(t,p)=>t==='A'?centerBottom+22+roles.A.indexOf(p)*24:centerBottom+roles.A.length*24+42+roles.B.indexOf(p)*24;
 let svg=`<svg viewBox="0 0 ${W} ${H}" style="min-width:${Math.min(W,Math.max(760,xs[data.total]+120))}px;height:${H}px" role="img" aria-label="${html(m.name)} 상단 이벤트 타임라인과 팀별 선수 투구 순서 시퀀스. 위 전반 왼쪽 팀 ${html(m.teams.A.name)}, 아래 전반 오른쪽 팀 ${html(m.teams.B.name)}">`;
 for(const t of ['A','B'])for(const pos of roles[t]){const y=Y(t,pos),p=initialRoster(m,t).find(p=>p.active&&p.position===pos);svg+=`<text x="8" y="${y+4}" fill="${colors[t]}">${pos==='?'?'?':pos}</text><text x="29" y="${y+4}" fill="#59655e">${html(p?`${p.number}번 ${p.name||''}`:'—')}</text><line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="#eef1ed"/>`;}
 svg+=`<line data-center-axis="true" x1="8" y1="${centerY}" x2="${right}" y2="${centerY}" stroke="#bdc6bf"/><text x="8" y="${centerY+3}" fill="#737e76">이벤트 · 투구 순서</text><text x="8" y="${Y('A','L')-14}" fill="${colors.A}">${html(m.teams.A.name.slice(0,16))} · 왼쪽 팀</text><text x="8" y="${Y('B','L')-14}" fill="${colors.B}">${html(m.teams.B.name.slice(0,16))} · 오른쪽 팀</text>`;
 for(const t of ['A','B']){const ps=points[t];if(ps.length)svg+=`<polyline data-sequence="${t}" points="${ps.map(p=>`${X(p.x)},${Y(t,p.position)}`).join(' ')}" fill="none" stroke="${colors[t]}" stroke-width="1.6" stroke-linejoin="round"/>`;for(const p of ps)svg+=`<circle cx="${X(p.x)}" cy="${Y(t,p.position)}" r="1.6" fill="${colors[t]}"><title>${p.x}회 · ${p.player}번 · ${p.position}</title></circle>`;}
 for(const e of events){const y=Y(e.team,e.position);svg+=`<text data-team="${e.team}" data-position="${e.position}" x="${X(e.x)}" y="${y+5}" text-anchor="middle" fill="${colors[e.team]}" style="font-size:15px;paint-order:stroke;stroke:var(--paper);stroke-width:3px">${eventIcon(e.code)}<title>${html(`${e.x}회 · ${e.player||'—'}번 ${e.code} · ${e.time||'시간 미입력'}`)}</title></text>`;}
 const slots={A:0,B:0};for(const e of markers){const y=centerY+(e.team==='A'?-25:24)+(e.team==='A'?-1:1)*(slots[e.team]++%2)*21,x=X(e.x),who=e.kind==='throw'?`${e.player}번 ${e.code}`:e.changes.map(c=>`${c.position} ${c.before||'—'}→${c.player||'—'}번 ${c.code}`).join(' / ');svg+=`<g data-event-info="${e.team}"><title>${html(`${HALF[e.half]} · ${e.x}회 · ${who} · ${e.time||'시간 미입력'}`)}</title><polyline data-event-connector="true" points="${x},${centerY} ${x},${y+(e.team==='A'?14:-4)} ${x+4},${y+(e.team==='A'?14:-4)}" fill="none" stroke="${colors[e.team]}" stroke-opacity=".45" stroke-width=".8"/><circle cx="${x}" cy="${centerY}" r="2" fill="${colors[e.team]}"/><text x="${x+4}" y="${y}" fill="${colors[e.team]}">${html(`${e.x}회 · ${who}`)}</text><text x="${x+4}" y="${y+11}" fill="#7c8781" style="font-size:9px">${html(e.time||'—')}</text></g>`;}
 if(data.boundary>0&&data.boundary<data.total)svg+=`<line x1="${X(data.boundary)}" y1="8" x2="${X(data.boundary)}" y2="${H-18}" stroke="#d0d8d2" stroke-dasharray="3 4"/><text x="${X(data.boundary)+4}" y="10" fill="#7c8781">후반</text>`;
 const step=Math.max(1,Math.ceil(data.total/10));for(const n of new Set([0,data.total,...Array.from({length:Math.floor(data.total/step)},(_,i)=>(i+1)*step)]))svg+=`<text data-center-tick="true" x="${X(n)}" y="${centerY+3}" text-anchor="middle" fill="#737e76" style="paint-order:stroke;stroke:var(--paper);stroke-width:4px;font-size:9px">${n}${n===data.total?'회':''}</text>`;
 return svg+'</svg>';
}
function timeline(m){const data=ganttData(m),wrap=document.createElement('div');wrap.className='timeline';const svg=timelineSVG(m,data),colors={A:'#245f91',B:'#b05b30'};
const plot=document.createElement('div');plot.innerHTML=svg;wrap.append(plot);const legend=document.createElement('p');legend.className='timeline-note';legend.innerHTML=`<span style="color:${colors.A}">● ${html(m.teams.A.name)}</span> <span style="color:${colors.B}">● ${html(m.teams.B.name)}</span> · 선: 팀별 투구 순서 · 가로축: 전체 투구 순서 · ★ 골 / △ L / ▽ H / ◇ P / ↔ 교체 / ↕ 위치 변경 · — 시간 미입력`;wrap.append(legend);const details=document.createElement('details');details.className='timeline-events';const summary=document.createElement('summary');summary.textContent=`이벤트 ${data.events.filter(e=>includesFactor('half',e.half)).length}건 보기`;details.append(summary);const list=document.createElement('div');list.className='event-list';for(const e of data.events.filter(e=>includesFactor('half',e.half))){const row=document.createElement('p');row.textContent=`${e.x}회 · ${HALF[e.half]} · ${m.teams[e.team].name} · ${e.position} · ${e.kind==='throw'?(e.player+'번 '+e.code):((e.before||'—')+'번 → '+(e.player||'—')+'번 '+e.code)} · ${e.time||'시간 미입력'}`;list.append(row);}details.append(list);wrap.append(details);return wrap;}
function renderSubstitutions(){const parent=$('substitutionList');parent.replaceChildren();let n=0;for(const m of analysisGames())for(const r of m.records)if(['substitution','positionChange'].includes(r.kind)&&includesFactor('half',r.half)&&includesFactor('team',teamKey(m,r.team))){n++;const row=document.createElement('p');row.textContent=`${gameLabel(m)} · ${HALF[r.half]} · ${m.teams[r.team].name} · ${r.eventTime||'시간 미입력'} · ${r.afterThrow}회 투구 후 ${r.kind==='positionChange'?'포지션 변경':'선수교체'}: ${lineup(r.before)} → ${lineup(r.after)}`;parent.append(row);}$('substitutionCount').textContent=n;}
function persistLibrary(){try{localStorage.setItem('goalball-analysis-v3',JSON.stringify(library));}catch{notice('전체 결과지 목록 저장 공간이 부족합니다. 원본 JSON 파일을 보관하세요.');}}
function mergeLibrary(incoming){let added=0,replaced=0,skipped=0;for(const m of incoming){const key=gameKey(m),i=library.findIndex(g=>gameKey(g)===key);if(i<0){library.push(m);added++;}else{const time=g=>g.exportedAt?Date.parse(g.exportedAt)||0:Math.max(0,...g.records.map(r=>Date.parse(r.recordedAt)||0));if(time(m)>=time(library[i])){library[i]=m;replaced++;}else skipped++;}selectedGames.add(key);}persistLibrary();renderGameChoices();buildFilters();renderReport();return {added,replaced,skipped};}
function renderGameChoices(){const parent=$('gameChoices');parent.replaceChildren();const detail=document.createElement('details');detail.className='factor-select game-select';const summary=document.createElement('summary'),update=()=>{summary.textContent=`경기 · ${library.filter(m=>selectedGames.has(gameKey(m))).length} / ${library.length}개 선택`;};update();const list=document.createElement('div');list.className='factor-options';if(!library.length)list.textContent='파일이나 폴더를 선택해 경기를 불러오세요.';for(const [text,on] of [['전체 선택',true],['선택 해제',false]]){const b=document.createElement('button');b.textContent=text;b.onclick=()=>{selectedGames=on?new Set(library.map(gameKey)):new Set();for(const input of list.querySelectorAll('input'))input.checked=on;update();buildFilters();renderReport();};list.append(b);}for(const m of library){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=selectedGames.has(gameKey(m));input.onchange=()=>{input.checked?selectedGames.add(gameKey(m)):selectedGames.delete(gameKey(m));update();buildFilters();renderReport();};label.append(input,document.createTextNode(`${gameLabel(m)} · ${m.teams.A.name} / ${m.teams.B.name}`));list.append(label);}detail.append(summary,list);detail.addEventListener('toggle',()=>{if(detail.open)for(const d of document.querySelectorAll('.factor-select'))if(d!==detail)d.open=false;});parent.append(detail);}
async function loadGames(files){const incoming=[],errors=[];for(const f of files){if(!f.name.toLowerCase().endsWith('.json'))continue;try{if(f.size>10*1024*1024)throw Error('10MB 초과');incoming.push(migrate(JSON.parse(await f.text())));}catch(e){errors.push(`${f.name}: ${e.message}`);}}const result=mergeLibrary(incoming);$('libraryStatus').textContent=`${result.added}경기 추가 · ${result.replaced}경기 최신 저장본 반영 · ${result.skipped}개 이전 저장본 제외${errors.length?' · 실패 '+errors.length+'개: '+errors.join(' / '):''}${!incoming.length&&!errors.length?' · JSON 파일이 없습니다.':''}`;}
try{const saved=JSON.parse(localStorage.getItem('goalball-analysis-v3')||'[]');if(Array.isArray(saved)){library=saved.map(migrate);selectedGames=new Set(library.map(gameKey));}}catch{library=[];}
$('loadGames').onclick=()=>$('gamesFile').click();$('loadFolder').onclick=()=>$('gamesFolder').click();for(const id of ['gamesFile','gamesFolder'])$(id).onchange=async e=>{await loadGames([...e.target.files]);e.target.value='';};$('addCurrent').onclick=()=>{mergeLibrary([{...structuredClone(match),exportedAt:new Date().toISOString()}]);$('libraryStatus').textContent='현재 경기의 사본을 추가했습니다. 이후 변경은 다시 추가하면 반영됩니다.';};
document.addEventListener('click',e=>{if(!e.target.closest('.factor-select'))for(const d of document.querySelectorAll('.factor-select'))d.open=false;});
renderPlayers();populateFilters();renderGameChoices();render();if(!match.registered)openMenu();
